+export default class extends Controller {
+  static targets = ["nameInput", "fieldKeyInput", "accordion", "panel"]
+  
+  connect() {
+    // Initialize field counter if not already set
+    if (typeof window.fieldCounter === 'undefined') {
+      window.fieldCounter = Date.now()
+    }
+  }
+
+  // Auto-generate field key from name
+  generateFieldKey(event) {
+    const nameInput = event.currentTarget
+    const fieldId = nameInput.dataset.fieldId
+    
+    // Find the field key input for this specific field
+    const fieldKeyInput = document.querySelector(`input[data-field-id="${fieldId}"][data-field="field_key"]`)
+    
+    if (fieldKeyInput && nameInput.value) {
+      fieldKeyInput.value = this.slugify(nameInput.value)
+    }
+  }
+  
+  // Update accordion header name when name field changes
+  updateAccordionName(event) {
+    const nameInput = event.currentTarget
+    const fieldId = nameInput.dataset.fieldId
+    const accordionItem = document.querySelector(`.accordion-item[data-field-id="${fieldId}"]`)
+    
+    if (accordionItem) {
+      const nameSpan = accordionItem.querySelector('.accordion-header span.font-medium')
+      if (nameSpan && nameInput.value) {
+        nameSpan.textContent = nameInput.value
+      }
+    }
+  }
