+  // Update position summary in accordion header
+  updatePositionSummary(event) {
+    const input = event.currentTarget
+    const fieldId = input.dataset.fieldId
+    const position = input.dataset.position
+    
+    const summary = document.querySelector(`.position-summary[data-field-id="${fieldId}"]`)
+    if (summary) {
